/// <summary>
/// Class to handle the cash sales desk daily summary.
/// </summary>
[SRSReportParameterAttribute(classStr(AVARUMCashSalesSummaryContract))]
internal final class AVARUMCashSalesSummaryController   extends SrsReportRunController
{
}

Method.Source:
/// <summary>
/// Pre-prompt contract modification
/// </summary>
protected void prePromptModifyContract()
{
    AVARUMCashSalesSummaryContract contract;
    super();

    contract = this.parmReportContract().parmRdpContract() as AVARUMCashSalesSummaryContract;
    if (args.dataset() == tableNum(AVARUMCashSalesDesk))
    {
        AVARUMCashSalesDesk         avaRUMCashSalesDesk = args.record();
        contract.parmTransDate(DateTimeUtil::date(avaRUMCashSalesDesk.ClosedAt));
    }
}

/// <summary>
/// Main entry point for the report controller
/// </summary>
/// <param name = "_args">Arguments</param>
public static void main(Args _args)
{
    AVARUMCashSalesSummaryController controller = new AVARUMCashSalesSummaryController();

    controller.parmReportName(ssrsReportStr(AVARUMCashSalesSummary, Report));
    controller.parmArgs(_args);
    controller.parmShowDialog(true);
    controller.startOperation();
}
